
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_tm_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_tm", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.756180677125829e-02, -3.716222478423986e-02, -3.658381074970007e-02, -3.574384702240196e-02, -3.451801397100828e-02, -3.271548159522430e-02, -3.003658205713602e-02, -2.601568601389709e-02, -2.009519952337059e-02, -1.280881478364260e-02, -9.984278675295725e-03, -3.748119959532149e-02, -4.499622650112108e-02, -2.741427615213088e-02, -1.270172231575115e-02, -2.896426490973997e-03, -1.395328252962057e-04, -7.466962611114938e-07, -2.425429221545093e-10, -2.887440629870077e-15]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


